using System;namespace Recovered.Gameplay {public static class PtlSimdPoints {static uint[] Read(SoundSetupImage m,uint p){return new uint[]{m.Word(p),m.Word(p+4),m.Word(p+8),m.Word(p+12)};}static void Store(SoundSetupImage m,uint p,uint[] v){for(uint i=0;i<4;i++)m.Word(p+i*4,v[i]);}static float F(uint w){return BitConverter.ToSingle(BitConverter.GetBytes(w),0);}public static void Transform(SoundSetupImage m,uint output,uint packed,uint matrix,int count,uint codes){unchecked{int groups=(count+3)>>2;if(groups<=0)return;uint[] a=new uint[16];for(uint i=0;i<16;i++)a[i]=m.Word(matrix+i*4);for(int group=0;group<groups;group++){uint source=packed+(uint)group*48,destination=output+(uint)group*48;uint[] z=null;for(uint col=0;col<3;col++){uint[] x=Read(m,source),y=Read(m,source+16),zz=Read(m,source+32),v=new uint[4];for(uint lane=0;lane<4;lane++){uint t0=PtlAffineRaw.Multiply32(a[col],x[lane]),t1=PtlAffineRaw.Multiply32(a[col+4],y[lane]),t2=PtlAffineRaw.Multiply32(a[col+8],zz[lane]);v[lane]=PtlAffineRaw.Add32(PtlAffineRaw.Add32(PtlAffineRaw.Add32(a[col+12],t0),t1),t2);}Store(m,destination+col*16,v);if(col==2)z=v;}float near=F(m.Word(0x973730));uint[] flags=new uint[4],far=Read(m,0x80e8f0);for(uint lane=0;lane<4;lane++){if(F(z[lane])<near)flags[lane]|=m.Word(0x80e870+lane*4);if(!(F(z[lane])<=F(far[lane])))flags[lane]|=m.Word(0x80e880+lane*4);}uint horizontal=m.Word(0x966378);uint[] negative=Read(m,0x80e8d0),slope=new uint[4];for(uint lane=0;lane<4;lane++)slope[lane]=PtlAffineRaw.Multiply32(PtlAffineRaw.Multiply32(horizontal,z[lane]),negative[lane]);uint[] left=Read(m,destination);for(uint lane=0;lane<4;lane++)if(F(left[lane])<F(slope[lane]))flags[lane]|=m.Word(0x80e890+lane*4);negative=Read(m,0x80e8d0);for(uint lane=0;lane<4;lane++)slope[lane]=PtlAffineRaw.Multiply32(slope[lane],negative[lane]);left=Read(m,destination);for(uint lane=0;lane<4;lane++)if(!(F(left[lane])<=F(slope[lane])))flags[lane]|=m.Word(0x80e8a0+lane*4);uint vertical=m.Word(0x97313c);negative=Read(m,0x80e8d0);for(uint lane=0;lane<4;lane++)slope[lane]=PtlAffineRaw.Multiply32(PtlAffineRaw.Multiply32(vertical,z[lane]),negative[lane]);uint[] top=Read(m,destination+16);for(uint lane=0;lane<4;lane++)if(F(top[lane])<F(slope[lane]))flags[lane]|=m.Word(0x80e8b0+lane*4);negative=Read(m,0x80e8d0);for(uint lane=0;lane<4;lane++)slope[lane]=PtlAffineRaw.Multiply32(slope[lane],negative[lane]);top=Read(m,destination+16);for(uint lane=0;lane<4;lane++)if(!(F(top[lane])<=F(slope[lane])))flags[lane]|=m.Word(0x80e8c0+lane*4);Store(m,codes+(uint)group*16,flags);}}}}}
